package clusterdata.datatypes;

import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.zip.GZIPInputStream;

public class TaskEventSource implements SourceFunction<TaskEvent> {
    private String filePath;

    public TaskEventSource(String filePath) {
        this.filePath = filePath;
    }

    @Override
    public void run(SourceContext<TaskEvent> ctx) throws Exception {
        try (GZIPInputStream gzip = new GZIPInputStream(new java.io.FileInputStream(filePath));
             BufferedReader reader = new BufferedReader(new InputStreamReader(gzip))) {

            String line;
            while ((line = reader.readLine()) != null) {
                TaskEvent event = parseTaskEvent(line);
                if (event != null) {
                    ctx.collect(event);
                }
            }
        }
    }

    @Override
    public void cancel() {
    }

    private TaskEvent parseTaskEvent(String line) {
        try {
            String[] fields = line.split(",", -1);
            if (fields.length < 13) {
                return null;
            }

            long timestamp = Long.parseLong(fields[0]);
            String missingInfo = fields[1];
            long jobId = Long.parseLong(fields[2]);
            long taskIndex = Long.parseLong(fields[3]);
            long machineId = Long.parseLong(fields[4]);
            int eventType = Integer.parseInt(fields[5]);
            String userName = fields[6];
            int schedulingClass = Integer.parseInt(fields[7]);
            int priority = Integer.parseInt(fields[8]);
            double cpuRequest = Double.parseDouble(fields[9]);
            double memoryRequest = Double.parseDouble(fields[10]);
            double diskRequest = Double.parseDouble(fields[11]);
            int constraintFlag = Integer.parseInt(fields[12]);

            return new TaskEvent(timestamp, missingInfo, jobId, taskIndex, machineId,
                    eventType, userName, schedulingClass, priority, cpuRequest,
                    memoryRequest, diskRequest, constraintFlag);
        } catch (Exception e) {
            return null;
        }
    }
}

