        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            // This is called when we have a timer - triggered from end of input
            Long jobId = ctx.getCurrentKey();

            // Get the maximum session count
            int maxTasks = 0;
            if (sessions.entries() != null) {
                for (java.util.Map.Entry<Long, Integer> entry : sessions.entries()) {
                    maxTasks = Math.max(maxTasks, entry.getValue());
                }
            }

            if (maxTasks > 0) {
                out.collect(new Tuple2<>(jobId, maxTasks));
            }
        }
    }

